parameters.jsCode:
const jobs = $('Get New Jobs').all();
const scored = $('Score & Draft').all();
const reviews = $input.all();
const candidateName = $('Candidate Profile').first().json.candidate_name;

// Index reviews by job id (reviews come from Groq main path OR NVIDIA fallback path)
const reviewsById = {};
for (const it of reviews) {
  const rv = (it && it.json) ? it.json : {};
  if (rv.job_id !== undefined && rv.job_id !== null) {
    reviewsById[String(rv.job_id)] = rv;
  }
}

const out = [];
for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i].json || {};
  const s = (scored[i] && scored[i].json && scored[i].json.output) ? scored[i].json.output : {};
  const rv = reviewsById[String(job.id)] || {};
  const hasReview = Object.keys(rv).length > 0;

  out.push({
    json: {
      id: job.id,
      job_title: job.job_title,
      company: job.company,
      location: job.location,
      job_description: job.job_description,
      job_url: job.job_url,
      contact_email: job.contact_email || "",
      candidate_name: candidateName,
      fit_score: (s.fit_score !== undefined && s.fit_score !== null) ? s.fit_score : null,
      fit_reason: s.fit_reason || "",
      cover_letter: s.cover_letter || "",
      approved: hasReview ? (rv.approved === true) : false,
      review_score: hasReview ? ((rv.score !== undefined && rv.score !== null) ? rv.score : null) : null,
      review_note: hasReview ? (rv.note || "") : "Second-opinion reviewer unavailable — saved for manual review.",
      review_source: hasReview ? (rv.source || "groq") : "none",
    },
    pairedItem: { item: i },
  });
}
return out;

const items = $input.all();
const rows = [];
for (const it of items) {
  const r = it.json || {};
  if (r.job_title || r.company) { rows.push(r); }
}
const total = rows.length;
let appliedCount = 0;
let reviewedCount = 0;
const lines = [];
for (const r of rows) {
  const status = r.status || "processed";
  if (status === "applied") { appliedCount++; } else { reviewedCount++; }
  const score = (r.fit_score === 0 || r.fit_score) ? r.fit_score : "N/A";
  const reason = r.fit_reason || "";
  lines.push(`• ${r.job_title || "Untitled"} @ ${r.company || "Unknown"} — fit ${score}/100 — ${status}`);
  if (reason) { lines.push(`    ${reason}`); }
}
const date = $now.toFormat("yyyy-LL-dd");
const subject = `Job digest ${date}: ${total} processed (${appliedCount} applied, ${reviewedCount} to review)`;
const body = [
  `Daily job digest — ${date}`,
  "",
  `Total processed: ${total}`,
  `Auto-applied: ${appliedCount}`,
  `Saved for review: ${reviewedCount}`,
  "",
  "Details:",
  ...lines,
].join("\n");
return [{ json: { subject, body, total } }];

const r = ($json && $json.output) ? $json.output : {};
const jobId = $('Get New Jobs').item.json.id;
return {
  json: {
    job_id: jobId,
    approved: r.approved === true,
    score: (r.score !== undefined && r.score !== null) ? r.score : null,
    note: r.note || "",
    source: "groq",
  }
};

const body = $json || {};
let content = "";
try { content = body.choices[0].message.content || ""; } catch (e) { content = ""; }

let parsed = {};
let ok = false;
if (content) {
  try {
    let c = String(content).trim();
    const m = c.match(/\{[\s\S]*\}/);
    if (m) { c = m[0]; }
    parsed = JSON.parse(c);
    ok = true;
  } catch (e) { ok = false; }
}

const jobId = $('Build NVIDIA Prompt').item.json.job_id;

return {
  json: {
    job_id: jobId,
    approved: ok ? (parsed.approved === true) : false,
    score: (ok && parsed.score !== undefined && parsed.score !== null) ? parsed.score : null,
    note: ok
      ? ((parsed.note || "Backup review") + " [NVIDIA fallback]")
      : "Both reviewers unavailable (Groq failed, NVIDIA fallback could not parse) — saved for manual review.",
    source: "nvidia",
  }
};
